  it("普通 usage 过期分片被删（对照组有效）", () => {
    expect(!usageExistsAfterPruneAll).toBeTruthy();
  });

  it("TrendStore.prune 删除 cutoff 前的明细+聚合分片", () => {
    expect(removed).toBe(2);
  });

  it("trend 过期分片被自身 prune 清理", () => {
    expect(trendShardsGoneAfterPrune).toBeTruthy();
  });
});

