  });

  it("version 非 1 返回 false", () => {
    expect(isClientProviderRenderer({
      version: 2, providers: ["anthropic"],
      render: () => {},
    })).toBe(false);
  });

  // #150 分片 2：伪装类型与元素级边界（变异驱动）
  it("函数载体即使属性齐全也拒绝", () => {
    const fake = () => {};
