  });

  it("providers 多元素含空串拒绝（全称量词）", () => {
    expect(isClientProviderRenderer({
      version: 1, providers: ["good", ""], render: () => {},
    })).toBe(false);
  });

  it("providers 元素为数组（length>0 非字符串）拒绝", () => {
    expect(isClientProviderRenderer({
      version: 1, providers: [[1]], render: () => {},
    })).toBe(false);
  });
});

// ---------------------------------------------------------------- usageError / usageOk

describe("usageError", () => {
  let err;

