    const pts = [
      { t: satNight, balance: 100, toppedUp: 90, granted: 10 },
      { t: sunEarly, balance: 99, toppedUp: 90, granted: 10 },  // 隔夜消耗 1 → 计入周日
      { t: sunNoon, balance: 94, toppedUp: 90, granted: 10 },   // 周日内消耗 5
