describe("UI 配置与面板锚点纯函数矩阵（#150 二阶段）", () => {
  // normalizeUiConfig：非法容器回退默认
  it("null 配置回退默认", () => {
    expect(normalizeUiConfig(null)).toEqual({ ...DEFAULT_UI_CONFIG });
  });

