  });

  // offset clamp 矩阵：负数压 0、超上限压 2000、小数四舍五入、数字字符串经 Number() 接受
  it("offsetX 负数压 0", () => {
    expect(normalizeUiConfig({ offsetX: -5 }).offsetX).toBe(0);
