  it("offsetX 小数四舍五入", () => {
    expect(normalizeUiConfig({ offsetX: 3.7 }).offsetX).toBe(4);
  });

  it("offsetX 边界 0 透传", () => {
    expect(normalizeUiConfig({ offsetX: 0 }).offsetX).toBe(0);
  });

  it("offsetX 边界 2000 透传", () => {
    expect(normalizeUiConfig({ offsetX: 2000 }).offsetX).toBe(2000);
  });

