  });

  it("底部锚点溢出钳到 6", () => {
    expect(panelTopForAnchor("bottom", 50, 60, 80, 8)).toBe(6);
  });

  it("顶部锚点过小钳到 6", () => {
    expect(panelTopForAnchor("top", 0, 0, 0, 4)).toBe(6);
  });

  // uiConfigFile 拼装规则
  it("ui.json 拼装", () => {
    expect(uiConfigFile("/root")).toBe(join("/root", "ui.json"));
  });
});

