  });

  it("0 参 fetchData 正常成功", async () => {
    expect((await probeZeroArg()).ok).toBe(true);
  });

  it("0 参 fetchData 走 fresh 通道", async () => {
    expect((await probeZeroArg()).status).toBe("fresh");
